const row = { ...$('Load creator data').item.json };
const out = String(($json && $json.output) || '');
const g = (lab) => { const m = out.match(new RegExp(lab + ':([\\s\\S]*?)(?=SPEECH:|SCENE:|TEXT:|$)', 'i')); return m ? m[1].trim() : ''; };
row._transcript = g('SPEECH') || null;
row._visual_desc = g('SCENE') || null;
row._overlay = g('TEXT') || null;
